'use strict';

// MODULES //

var isNodeREPL = require( '@stdlib/assert/is-node-repl' );
var Autosize = require( '@stdlib/plot/vega/autosize/ctor' );
var Padding = require( '@stdlib/plot/vega/padding/ctor' );
var Title = require( '@stdlib/plot/vega/title/ctor' );


// MAIN //

/**
* Returns defaults.
*
* @private
* @returns {Object} defaults
*
* @example
* var obj = defaults();
* // returns {...}
*/
function defaults() {
	var isREPL = isNodeREPL();
	return {
		// Autosize configuration:
		'autosize': new Autosize({
			'type': 'none',
			'contains': 'padding',
			'resize': false
		}),

		// Height (in pixels):
		'height': 480,

		// Chart padding (in pixels):
		'padding': new Padding({
			'bottom': 80,
			'left': 90,
			'right': 20,
			'top': 80
		}),

		// Chart title:
		'title': new Title({
			// Horizontal title and subtitle text alignment:
			'align': 'center',

			// Anchor position for placing title and subtitle:
			'anchor': 'middle',

			// Angle (in degrees) of the title and subtitle text:
			'angle': 0,

			// Boolean indicating whether to include ARIA attributes in SVG output:
			'aria': true,

			// Vertical baseline of the title and subtitle text:
			'baseline': 'alphabetic',

			// Color of the title text:
			'color': '#000',

			// Horizontal offset (in pixels) added to the title and subtitle x-coordinate:
			'dx': 10,

			// Vertical offset (in pixels) added to the title and subtitle y-coordinate:
			'dy': 0,

			// Font name of the title text:
			'font': 'sans-serif',

			// Font size of the title text:
			'fontSize': 14,

			// Font style of the title text:
			'fontStyle': 'normal',

			// Font weight of the title text:
			'fontWeight': 'bold',

			// Reference frame for the anchor position:
			'frame': 'bounds',

			// Maximum allowed length (in pixels) of title and subtitle text:
			'limit': 10000, // note: effectively unlimited

			// Line height for multi-line title text:
			'lineHeight': 1.5,

			// Orthogonal offset (in pixels) by which to displace the title from its position along the edge of the chart:
			'offset': 0,

			// Title and subtitle orientation relative to the chart:
			'orient': 'top',

			// Subtitle text:
			'subtitle': void 0,

			// Color of the subtitle text:
			'subtitleColor': '#000',

			// Font name for the subtitle text:
			'subtitleFont': 'sans-serif',

			// Font size for the subtitle text:
			'subtitleFontSize': 11,

			// Font style for the subtitle text:
			'subtitleFontStyle': 'italic',

			// Font weight for the subtitle text:
			'subtitleFontWeight': 'normal',

			// Line height for multi-line subtitle text:
			'subtitleLineHeight': 1.5,

			// Padding (in pixels) between title and subtitle text:
			'subtitlePadding': 2,

			// Title text:
			'text': [],

			// Integer z-index indicating the layering of a title group relative to other axis, mark, and legend groups:
			'zindex': 0
		}),

		// Chart viewer:
		'viewer': ( isREPL ) ? 'window' : 'stdout',

		// Width (in pixels):
		'width': 600
	};
}


// EXPORTS //

module.exports = defaults;
